INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', '27', 'REF-01009', NULL, 1, 1, NULL, '[backward 2026-09-28 06:49] TARGETED, NOT EXHAUSTIVE: this pass followed only the two backward citations anchoring REF-01009''s own ramp-slope criterion (its Supplementary Appendix 1 footnotes 3 and 4), not all ~38 references in its bibliography. Citation 4, the Uganda Building Control (Accessibility Standards for Persons with Disabilities) Code 2019, was retrieved in full and independently admitted as REF-01010 with its own extraction (parameter 3, MOB, 1:12 max gradient, clause 12(3)(a)). Citation 3, a 2014 ''practical guide'' (asksource.info), was only reachable as a secondary quotation -- a direct retrieval attempt returned HTTP 503 -- and is filed as a REFERENCE-ONLY research_code_lead (lead_id 90) rather than admitted. A full depth-1 backward pass over the remaining references is not done and is not claimed.
INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-01009', 'journal_article', NULL, 0, NULL, NULL, 0, NULL, 2024, NULL, 'Adapting and pilot testing a tool to assess the accessibility of primary health facilities for people with disabilities in Luuka District, Uganda', NULL, NULL, NULL, 'en', 'native_title_verified', NULL, NULL, NULL, NULL, NULL, 0, 'International Journal for Equity in Health', NULL, '23', '1', NULL, NULL, '237', 'Springer Science and Business Media LLC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.1186/s12939-024-02314-0', '39538333', NULL, NULL, NULL, 'https://doi.org/10.1186/s12939-024-02314-0', '2026-09-28', NULL, NULL, 1, 'co1', 'UG', 'Eight Ugandan youth researchers with disabilities (aged 18-35), members of the MRC/UVRI & LSHTM Uganda Research Unit''s ''Disability Youth Investigates'' capacity-building programme, co-adapted the Disability Awareness Checklist across three rounds of the study''s own design process: in Round 1 they reviewed the individual questions and proposed Uganda-specific changes (e.g. removing guide-dog questions, adapting public-transport questions); in Round 3 they held a round-table review of the draft adapted tool with the study team. ALL EIGHT then underwent a 2-day facilitator training; six of the eight were subsequently selected to co-conduct the five-facility pilot audit as trainee facilitators, each paired with a non-disabled peer. Disabilities NAMED among the six pilot facilitators: Deaf (one), albinism (one), visual impairment (one); the other three are not individually described. No mobility impairment is named among any of the eight -- see R13 population-match note on this source''s parameter-3 extraction.', 'participatory_research', NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-28 06:44', 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:39', 'session_2026-09-28-research-batch-21-selection', NULL, NULL, 1, NULL, '237', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CORRECTED', '2026-09-28 doi_resolution_outcome CORRECTED (add-source omitted --doi-resolution-outcome at admission; the DOI was confirmed resolving to this exact record via Europe PMC''s search API this session (pmid 39538333, doi 10.1186/s12939-024-02314-0 both returned in the same record).). Replaced text was: None || 2026-09-28 co1_provenance CORRECTED (Caught by an independent adversarial pass, not self-caught: the persisted JATS XML (retrieval-log/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/18ef7d575e63330c.xml) says ALL EIGHT youth researchers underwent the 2-day facilitator training, and SIX of the eight were then selected for the pilot -- the original text wrongly said ''six of the eight then underwent facilitator training'', reversing which number attaches to which step.). Replaced text was: "Eight Ugandan youth researchers with disabilities (aged 18-35), members of the MRC/UVRI & LSHTM Uganda Research Unit''s ''Disability Youth Investigates'' capacity-building programme, co-adapted the Disability Awareness Checklist across three rounds of the study''s own design process: in Round 1 they reviewed the individual questions and proposed Uganda-specific changes (e.g. removing guide-dog questions, adapting public-transport questions); in Round 3 they held a round-table review of the draft adapted tool with the study team. Six of the eight then underwent facilitator training and co-conducted the five-facility pilot audit as trainee facilitators, each paired with a non-disabled peer. Disabilities NAMED among the six pilot facilitators: Deaf (one), albinism (one), visual impairment (one); the other three are not individually described. No mobility impairment is named among any of the eight -- see R13 population-match note on this source''s parameter-3 extraction."', NULL, NULL, NULL, NULL, 'intrinsic', 'captured', 'mined', NULL, NULL, NULL, NULL, 'CLOSED', 'direct-render', NULL);
