ative_title_verified', NULL, NULL, NULL, NULL, NULL, 0, 'Ciência &amp; Saúde Coletiva', NULL, '21', '10', NULL, NULL, NULL, 'FapUNIFESP (SciELO)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.1590/1413-812320152110.20052016', '27783788', NULL, NULL, NULL, 'https://doi.org/10.1590/1413-812320152110.20052016', '2026-09-28', NULL, NULL, 3, 'clinical', 'BR', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-28 06:54', 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:35', 'session_2026-09-28-research-batch-21-selection', NULL, NULL, 1, NULL, '3153-3160', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CORRECTED', '2026-09-28 doi_resolution_outcome CORRECTED (add-source omitted --doi-resolution-outcome at admission; the DOI was confirmed resolving to this exact record via Europe PMC''s search API this session (pmid 27783788, doi 10.1590/1413-812320152110.20052016 both returned in the same record), and independently via doi.org''s own redirect to the SciELO PID this session.). Replaced text was: None', NULL, NULL, NULL, NULL, 'lower_control', 'captured', 'pending', NULL, NULL, NULL, NULL, 'CLOSED', 'direct-render', NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-054', 'SW', 'P3', 'CLOSED-DUPLICATE', NULL, NULL, 'A DOI-LESS SOURCE HAS NO SANCTIONED WAY TO CORRECT A BIBLIOGRAPHIC FIELD AFTER ADMISSION. Found admitting REF-01010 (the Uganda Building Control Code 2019, a statutory instrument, no DOI): add-source''s own --pages flag was simply not passed at admission (my own omission, not a tooling defect on its own), but once the row exists, nothing can fix it -- amend-source explicitly REFUSES bibliographic fields (''use db.py correct-source, which takes it from the logged payload''), and correct-source itself REFUSES outright for any ref_id with no DOI (''no DOI, so no payload can be keyed to it''). This closes the loop with no writer: research_batch_dod''s R3 (clause/section/page citation on regulatory-stratum sources) reads evidence_sources.pages/article_number specifically -- not source_value_extractions'' own loc_section/loc_subsection/loc_clause, which REF-01010''s extraction_id=70 DOES carry correctly (loc_section=12, loc_subsection=3, loc_clause=a) -- so a source can be genuinely, precisely clause-cited at the extraction level and still fail R3 forever, for every DOI-less regulatory/statutory/code source this project ever admits, with no remediation path except getting --pages right on the FIRST add-source call. WHAT WOULD CLOSE IT: either (a) correct-source gains a DOI-less path keyed to a persisted retrieval-log artefact instead of a DOI''d payload (the artefact IS the authority for a statute the way a CrossRef record is for a journal article), or (b) R3''s own check reads source_value_extractions.loc_* as an alternative satisfying condition to evidence_sources.pages/article_number, since the extraction-level locator is where R3''s actual concern (a clause a reader can find) is already precisely recorded. This batch''s own occurrence is recorded as a REASONED WAIVER, not remediated: REF-01010.pages stays unset; the true locator is source_value_extractions.extraction_id=70 (loc_section=12, loc_subsection=3, loc_clause=a), byte-verified against the persisted primary PDF (retrieval-log/session_2026-09-28-research-batch-21-selection/35c03adeb327d61c.pdf, page 15 of 42). || CORRECTED 2026-09-28: CLOSED AS A DUPLICATE, caught by an independent adversarial pass, not self-caught: this is GAP-043 item (1) refiled under a new id -- same mechanism (''correct-source keys its payload BY DOI... amend-source refuses anything in _CORRECTABLE by design. So for a row with no DOI both columns are now unreachable by EVERY sanctioned writer''), same conclusion, filed twice. Rule 5 (''never write the same fact into a second table'') applies to the gaps register too. The genuinely NEW content here (REF-01010 as a concrete pages/article_number instance rather than journal_name/publisher; the observation that R3''s check reads evidence_sources.pages/article_number and not source_value_extractions.loc_*, so a precisely clause-cited extraction can still fail R3 forever) is folded into GAP-043 instead. See GAP-043 for the live record; this id is superseded by it.', '2026-09-28 07:08', 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:36', 'session_2026-09-28-research-batch-21-selection', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "research_code_leads" ("lead_id", "jurisdiction", "standard_name", "clause", "status", "recovered_from", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (89, 'UG', 'The Building Control (Accessibility Standards For Persons With Disabilities) Code, 2019 (S.I. 2019 No. 52)', '12(3)(a)', 'RETRIEVED', 'Admitted in full as REF-01010 (evidence_type=code, tier=6, scope=intrinsic); source_value_extractions.extraction_id=70 under parameter_id=3 (MOB): 1:12 max gradient. Primary PDF fetched directly from kcca.go.ug and persisted this session.', 'Statutory instrument, in force 26 July 2019 (Uganda Gazette No. 35, Vol. CXII, Supplement No. 18); made under s.46 Building Control Act 2013; signed 2 October 2018 by Hon. Monica Azuba Ntege, Minister of Works and Transport. Clause 12(1) frames the whole ramp requirement around wheelchair users.', '2026-09-28 06:48', 'session_2026-09-28-research-batch-21-selection', NULL, NULL);
INSERT INTO "research_code_leads" ("lead_id", "jurisdiction", "standard_name", "clause", "status", "recovered_from", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (90, 'UG', 'Accessibility standards: a practical guide to create a barrier-free physical environment in Uganda (2014)', '1.3 (Degree of slope of ramp)', 'REFERENCE-ONLY', 'Found only as a secondary quotation in Mactaggart et al. 2024 Supplementary Appendix 1 (REF-01009): ''The maximum recommended slope of ramps is 1:20 (5 cm pr. m)... For small level differences and very short ramps of about 1 meter, the maximum slope of such a ramp should be 1:10.'' Mactaggart''s own citation additionally labels this ''UNAPD Accessibility Standards 2010'', suggesting it republishes a Uganda National Action on Physical Disability standard; that relationship is not independently confirmed. Direct retrieval attempt at asksource.info/resources/accessibility-standards-a-practical-guide-create-a-barrier-free-physical-environment returned HTTP 503 this session -- not a terminal answer per R10, retry later.', NULL, '2026-09-28 06:48', 'session_2026-09-28-research-batch-21-selection', NULL, NULL);
INSERT INTO "research_code_leads" ("lead_id", "jurisdiction", "standard_name", "clause", "status", "recovered_from", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (91, 'ES', 'Código Técnico de la Edificación, DB-SUA 9 (Accesibilidad)', 'ramp slope table (not independently retrieved)', 'REFERENCE-ONLY', 'Found via web search (exec_id 101), restated identically across multiple commercial-vendor/blog pages (certicalia.com, accesibilis.es, valida.es, others), not retrieved from the primary CTE/DB-SUA text itself: tiered max slope 10% (<3m run), 8% (<6m run), 6% (longer); min width 1.20m; handrail required from 6%. NOT independently verified against the primary document this session.', NULL, '2026-09-28 06:58', 'session_2026-09-28-research-batch-21-selection', NULL, NULL);
INSERT INTO "research_code_leads" ("lead_id", "jurisdiction", "standard_name", "clause", "status", "recovered_from", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (92, 'FR', 'Arrêtés du 8 décembre 2014 et du 20 avril 2017 (accessibilité ERP)', 'ramp slope provisions (not independently retrieved)', 'REFERENCE-ONLY', 'Found via web search (exec_id 102), restated across multiple vendor/blog pages (handinorme.com, manutan-collectivites.fr, others), not retrieved from the primary arrêté texts: 5% recommended maximum; exceptionally 8% under 2m run or 10% under 0.5m run; movable ramps up to 12% under 0.5m run. NOT independently verified against the primary regulatory text this session.', NULL, '2026-09-28 06:58', 'session_2026-09-28-research-batch-21-selection', NULL, NULL);
INSERT INTO "research_code_leads" ("lead_id", "jurisdiction", "standard_name", "clause", "status", "recovered_from", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (93, 'ES', 'CERMI Comunidad de Madrid / Ayuntamiento de Madrid — Metodología para la evaluación e implementación de Accesibilidad Universal en espacios públicos de la ciudad de Madrid (2018)', 'p.24, ''Pendientes longitudinales máximas'' and ''Características generales''', 'RETRIEVED', 'Retrieved directly (not secondary-sourced): retrieval-log/session_2026-09-28-research-batch-21-selection/76d6a5953998c402.pdf p.24 of 69, cross-checked via derived text-extract retrieval-log/session_2026-09-28-research-batch-21-selection/d1c5d900e01f9f10.json. Verbatim: ''Rampas de menos de 3 m. pendiente máxima 10%. Rampas de entre 3 y 10 m. pendiente máxima 8%.'' (longitudinal/running slope, tiered by ramp length) and ''La pendiente transversal máxima será del 2%'' (cross-slope, a different axis). Staged as search_candidates.candidate_id=132, not yet admitted as a full evidence_sources row (CERMI''s actual authorial role not yet read).', NULL, '2026-09-28 07:34', 'session_2026-09-28-research-batch-21-selection', NULL, NULL);
