INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-28-resea-REF-01009-MOB', 'REF-01009', 'MOB', 'Co-production/facilitation by 8 Ugandan disabled youth researchers (Deaf 1, albinism 1, visual impairment 1, three unspecified); the ramp-compliance MEASUREMENT itself is a structural/checklist audit of buildings with no wheelchair-using participants tested against the ramps', NULL, 'PARTIAL', 'R13: no mobility impairment is named among the co-producing/facilitating youth researchers, and the study design is a checklist audit (no participants tested navigating the ramps) rather than a test of MOB-population users -- ''no-participants'' is R13''s own explicit PROXY case. See extraction_id=71. || REGRADED 2026-09-28 by session_2026-09-28-research-batch-21-selection: PROXY -> PARTIAL. Owner ruling 2026-09-25 (references/project-standards.md, ''A FACILITY AUDIT''S POPULATION GRADE DOES NOT TURN ON WHETHER ITS AUDITORS WERE DISABLED''), applied on contact (rule 0), caught by an independent adversarial pass: this batch''s original PROXY grade reasoned from the disability status of the CO-PRODUCING YOUTH RESEARCHERS AND FACILITATORS -- exactly the criterion the ruling names as irrelevant to population-match directness (''Whether an audit''s participants were disabled is a Co-1 question, not a criterion of population-match directness''). The Co-1 tier/warrant on this source''s evidence_sources row is UNCHANGED by this correction -- that is a separate, source-level question the ruling explicitly preserves. Grading on who is served and what was measured instead, per REF-01006/REF-01007''s precedent (applied, not reopened): the population served is MOB (this study audits primary health facilities'' physical accessibility for people with disabilities broadly, including the ramp/entrance features that bear directly on mobility-impaired users); the measurement is one step removed -- a trained-facilitator checklist audit of 5 facilities'' structural features (ramp slope, width, handrails, surface), not an observation of mobility-impaired people actually negotiating the ramps. Not PROXY: no substitution of a general/child/non-disabled population.', '2026-09-28 07:02', 'session_2026-09-28-research-batch-21-selection', 'REF-01009', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-28-resea-REF-01011-MOB', 'REF-01011', 'MOB', 'No human participants: a structural checklist audit of 90 buildings against NBR 9050, with no disabled people tested navigating the ramps', NULL, 'PARTIAL', 'R13: ''no-participants'' is R13''s own explicit PROXY case -- this is a pure built-environment audit, not a study of MOB-population users. See extraction_id=72. || REGRADED 2026-09-28 by session_2026-09-28-research-batch-21-selection: PROXY -> PARTIAL. Owner ruling 2026-09-25 (references/project-standards.md, ''A FACILITY AUDIT''S POPULATION GRADE DOES NOT TURN ON WHETHER ITS AUDITORS WERE DISABLED''), applied on contact (rule 0), caught by an independent adversarial pass: this batch''s original PROXY grade followed the harness research contract''s one-line R13 summary (''...no-participants = PROXY''), which that ruling supersedes as applied to a facility audit -- REF-01007 (the same study class: a Brazilian primary-care facility census/audit) was re-graded PROXY -> PARTIAL on exactly this point, and that precedent is applied here, not reopened. Grading on who is served and what was measured instead: the population served is MOB (this is a checklist audit of buildings'' physical accessibility features -- ramp, floor, door width -- items that bear directly on mobility-impaired users); the measurement is one step removed, as REF-01006/REF-01007''s own PARTIAL notes record -- a checklist compliance reading of 90 buildings, not an observation of disabled people negotiating the ramps. Not PROXY: no substitution of a general/child/non-disabled population is involved.', '2026-09-28 07:02', 'session_2026-09-28-research-batch-21-selection', 'REF-01011', NULL);
