INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (64, 'REF-01009', 'Ramp meets access standards', 'EN', 'Supplementary Table 2', 'Ramp meets access standards1 [footnote 1: Composite score if ramp slope (min 1:12) and width (min 1300mm) is acceptable, has handrails and is non-slip]', NULL, '2026-09-28 07:02', 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:02', 'session_2026-09-28-research-batch-21-selection');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (65, 'REF-01010', 'gradient measured along the centre line', 'EN', 'Part II, section 12(3)(a)', 'A ramp provided under this Code shall— (a) have a gradient measured along the centre line, that is not steeper than 1:12 as prescribed in Figure 10 in the Schedule', NULL, '2026-09-28 07:02', 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:02', 'session_2026-09-28-research-batch-21-selection');
