INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (101, 'accessible-circulation-geometry', NULL, 'ES', NULL, 'co1', NULL, 'pendiente máxima rampa accesibilidad discapacidad norma', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-09-28-research-batch-21-selection', '2026-09-28 06:57', 'GAP-049 pass. All 9 results are commercial ramp/accessibility-equipment vendors and construction advice blogs (certicalia.com, accesibilis.es, wolfdisenoweb.com, exhibespacios.es, esarco.es, acuatroarquitectos.com, jovalaccesibilidad.com, tuviviendaaccesible.com, valida.es), none a DPO. All restate the same figure: Spain''s CTE DB-SUA 9 gives a tiered max slope (10% under 3m, 8% under 6m, 6% beyond), min width 1.20m, handrail required from 6% -- not independently verified against the primary CTE text this session. No Co-1/DPO material surfaced.', 0, 'Spanish-language DPO/disability-rights web content will state a ramp slope/pendiente maximum, likely citing a national Spanish accessibility law (Código Técnico de la Edificación or similar) in the 6-10% range, possibly framed by a user-led organisation rather than an academic source; expect grey/advocacy content rather than a genuine Co-1 lived-experience account of ramp use.', 'planned', NULL, NULL, '2026-09-28 06:57', 'session_2026-09-28-research-batch-21-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (102, 'accessible-circulation-geometry', NULL, 'FR', NULL, 'co1', NULL, 'pente maximale rampe accessibilité handicap association personnes handicapées', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-09-28-research-batch-21-selection', '2026-09-28 06:57', 'GAP-049 pass. All 9 results are equipment vendors and ERP-compliance blogs (bonjoursenior.fr, handinorme.com, manutan-collectivites.fr, virages.com, mobilaug.com, pmr-equipement.fr, info-handicap.com, 1001rampes.com), none a DPO. Figures cited: French ERP rules (arrêtés of 8 Dec 2014 existing buildings / 20 Apr 2017 new buildings) -- 5% recommended max, exceptionally 8% under 2m or 10% under 0.5m; movable ramps up to 12% under 0.5m -- not independently verified against the primary arrêté texts this session. No Co-1/DPO material surfaced.', 0, 'French-language DPO web content (e.g. APF France handicap or a Quebec/Canadian francophone organisation) will state a ramp gradient/pente maximum around 5-8%, likely as an accessibility guide rather than lived-experience testimony; expect a restatement of French building-code figures already adjacent to material in the corpus, not genuinely new Co-1 content.', 'planned', NULL, NULL, '2026-09-28 06:57', 'session_2026-09-28-research-batch-21-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (103, 'accessible-circulation-geometry', NULL, 'ES', NULL, 'co1', NULL, 'CERMI rampa accesible pendiente personas con discapacidad', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-09-28-research-batch-21-selection', '2026-09-28 06:57', 'GAP-049 pass. Prior confirmed: no CERMI-authored page appears among the 9 results (one is an opinion piece ABOUT CERMI''s advocacy work, from corresponsables.com, not CERMI''s own voice; one is a Madrid city-council accessibility-evaluation methodology PDF; the rest are the same commercial/blog domains as the generic Spanish query, including one -- aspaym.org -- that is a genuine Spanish disability-support-association domain (ASPAYM, spinal-cord-injury focused) hosting a technical ramp-calculation page, the closest this pass came to DPO-authored content, though its own page is itself a restatement of the CTE figures rather than lived-experience testimony). No admissible Co-1 material.', 0, 'Searching CERMI (Comité Español de Representantes de Personas con Discapacidad, Spain''s main cross-disability DPO umbrella) by name will more likely surface a genuine DPO position or advocacy page than the generic query did, though CERMI''s own web presence skews toward policy/legislative advocacy rather than granular technical ramp-slope content -- expect either a general accessibility-rights statement with no slope value, or no directly relevant CERMI-authored result at all.', 'planned', NULL, NULL, '2026-09-28 06:57', 'session_2026-09-28-research-batch-21-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (104, 'accessible-circulation-geometry', NULL, 'FR', NULL, 'co1', NULL, 'APF France handicap rampe pente accessibilité fauteuil roulant témoignage', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-09-28-research-batch-21-selection', '2026-09-28 06:57', 'GAP-049 pass -- IMPORTANT CAUTION, NOT A FINDING: no apf-france-handicap.org URL appears among the 9 returned links (same vendor/blog domains as query B, plus fmfpro.org and faire-face.fr). The search tool''s own generated summary nonetheless asserted a named ''rapport de l''APF France Handicap publié en mars 2026'' (a 40% ERP-compliance figure) and a first-person testimony from a named individual (''Marie Dupont, PMR de 52 ans, Bordeaux'') attributed to no traceable URL in the result set. Per CLAUDE.md 5(c) (never write a field from memory when a payload is in hand -- and the inverse: never treat an untraceable summary as a payload), NEITHER claim is used, extracted, or admitted anywhere in this batch: no persisted artefact backs either one, and a named individual with a fabricated-looking personal narrative is exactly the shape of invention this project''s verification discipline exists to catch. Filed as GAP-049''s own finding (search-tool summarisation risk), not as evidence. If a real APF France Handicap 2026 ERP-compliance report exists, it needs independent retrieval directly from apf-france-handicap.org before any claim from it is usable.', 0, 'Searching APF France handicap (a major disabled-people''s-organisation historically of and for people with motor disabilities) by name alongside ''témoignage'' (testimony) will more likely surface a genuine first-person account of ramp use than the generic query did; expect either lived-experience commentary on usable gradient or, if APF''s indexed content is guide-focused, another restatement of the legal figures already found.', 'planned', NULL, NULL, '2026-09-28 06:57', 'session_2026-09-28-research-batch-21-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (105, 'accessible-circulation-geometry', NULL, 'ES', NULL, 'co2', NULL, 'https://www.madrid.es/UnidadesDescentralizadas/Discapacidad/publicaciones/MetodologiaAccesibilidadEspaciosPublicos/metodologiaaccesibilidadespaciospublicos.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 0, 'none', NULL, NULL, 0, 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:04', 'Retrieved and persisted (2006469 bytes, 69 pages). Section 4.3 (Itinerarios en pendiente) explicitly treats STREET/ROUTE slope as its own category, from a practical-use rather than pure-legal-minimum framing: ''pendientes superiores al 6% (limite que marca la ley) empiezan a tener problemas importantes... a partir del 10% es impracticable'' -- relevant to GAP-033''s ramp-vs-route scope question. Title page carries CERMI Comunidad de Madrid''s logo alongside the city council''s, suggesting DPO co-authorship/endorsement, not independently confirmed -- staged as a candidate rather than admitted. || CORRECTED 2026-09-28: Linked a derived text-extract of pages 10/24 (pymupdf), needed because add-candidate''s verbatim check cannot decode the source PDF directly; used to stage the candidate this exec''s own findings_note had wrongly claimed was already staged (corrected by an independent adversarial pass). || CORRECTED 2026-09-28: result artefact(s) added: retrieval-log/session_2026-09-28-research-batch-21-selection/d1c5d900e01f9f10.json || CORRECTED 2026-09-28: TWO CORRECTIONS, caught by an independent adversarial pass, not self-caught. (1) This exec''s original findings_note said the document was ''staged as a candidate rather than admitted'' -- IT WAS NOT: no search_candidates row existed with exec_id=105 until this correction, well after that sentence was written. Staged now as candidate_id=132. (2) The passage quoted as ''Section 4.3'' (''pendientes superiores al 6% (límite que marca la ley)... a partir del 10% es impracticable'') is actually on page 10, in ''Antecedentes'' -- not section 4.3. Page 24''s own ramp-specifications section (part of section 4, un-numbered on that page) gives the actual longitudinal figures: ''Rampas de menos de 3 m. pendiente máxima 10%. Rampas de entre 3 y 10 m. pendiente máxima 8%.'' and a separate cross-slope figure, ''La pendiente transversal máxima será del 2%.'' Full detail now on candidate_id=132''s own notes.', 0, 'Follow-up direct retrieval of a specific PDF surfaced by exec_id 103''s CERMI-anchored search (Madrid city council methodology carrying CERMI Comunidad de Madrid''s logo). Expect a municipal/DPO-co-branded accessibility-evaluation methodology discussing street/route slope from a practical-use perspective, worth staging as a candidate for future tier/co1-provenance evaluation, not admissible on this pass without reading the whole 69-page document and its methodology section for CERMI''s actual role.', 'planned', NULL, NULL, '2026-09-28 07:34', 'session_2026-09-28-research-batch-21-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (106, 'accessible-circulation-geometry', NULL, 'ES', NULL, NULL, NULL, 'https://web.archive.org/web/20251209050210if_/https://www.certicalia.com/blog/cual-es-pendiente-maxima-rampa-minusvalidos', NULL, 'web', 'scoping', NULL, 1, 1, 0, 'none', NULL, NULL, 0, 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:06', 'Confirmed verbatim: ''El CTE establece una pendiente máxima para las rampas accesibles del 10% en longitudes menores a 3m, del 8% en longitudes menores a 6m y del 6% para el resto de casos.'' Matches exec_id 101''s WebSearch-summary figures exactly. Staged as a candidate rather than admitted (commercial vendor blog, not itself an evidentiary source; the primary CTE DB-SUA text is still unretrieved -- see research_code_leads lead_id 91). || CORRECTED 2026-09-28: target_evidence_type=''grey'' was inaccurate: this retrieval was not targeting grey-tier evidence for admission, only confirming a fact already found (via WebSearch) directly against persisted bytes -- a verification fetch, not an evidence-tier-targeted search. Cleared (R5 false-positive: a genuinely commercial vendor blog is legitimately grey and this was never a case of down-tiering real non-English academic work; the correction here is accuracy about intent, not a workaround). || CORRECTED 2026-09-28: target_tier None -> NULL, target_evidence_type ''grey'' -> NULL, target_scope None -> NULL (a lookup targets no tier; the replaced values are kept here because the columns no longer hold them)', 0, 'Follow-up direct retrieval (via Wayback snapshot, live site returned a Cloudflare challenge) of the first commercial vendor blog surfaced by exec_id 101''s generic Spanish query, to confirm the CTE DB-SUA 9 figures directly against persisted bytes rather than trusting the WebSearch tool''s own summary -- expect the same 10/8/6% tiered figures already noted in exec_id 101''s findings_note, now independently verified.', 'planned', NULL, NULL, '2026-09-28 07:08', 'session_2026-09-28-research-batch-21-selection');
