INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (131, 106, 'accessible-circulation-geometry', NULL, 'OUT-OF-SCOPE', 'Certicalia — ¿Cuál es la pendiente máxima de una rampa para minusválidos?', 'https://www.certicalia.com/blog/cual-es-pendiente-maxima-rampa-minusvalidos (persisted via Wayback: retrieval-log/session_2026-09-28-research-batch-21-selection/6a5ded49d27d3a48.html). R9 PRE-CHECKED: no DOI, commercial blog; not held by any evidence_sources row or staged candidate.', 'RESOLVED', 3, 0, 'Commercial ramp/construction-equipment vendor''s own marketing blog, not an evidentiary source -- restates Spain''s CTE DB-SUA 9 building-code figures with no independent measurement, testimony, or citation of its own. Representative of ALL 9 results this search''s query shape returned (see exec_id 101''s findings_note): GAP-049''s finding that this query shape surfaces commercial intermediaries, not DPO/Co-1 material.', 'R7 candidate (this batch''s multilingual GAP-049 pass screened 36+ results with only prose findings_notes to show for it; this one is staged formally). The primary CTE DB-SUA 9 text itself remains unretrieved and is filed separately as research_code_leads lead_id 91 (REFERENCE-ONLY).', 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:07', NULL, 'retrieval-log/session_2026-09-28-research-batch-21-selection/6a5ded49d27d3a48.html', 'El CTE establece una pendiente máxima para las rampas accesibles del 10% en longitudes menores a 3m, del 8% en longitudes menores a 6m y del 6% para el resto de casos.', '2026-09-28 07:07', 'session_2026-09-28-research-batch-21-selection');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (132, 105, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Ayuntamiento de Madrid / CERMI Comunidad de Madrid — Metodología para la evaluación e implementación de Accesibilidad Universal en espacios públicos de la ciudad de Madrid (diciembre 2018)', 'https://www.madrid.es/UnidadesDescentralizadas/Discapacidad/publicaciones/MetodologiaAccesibilidadEspaciosPublicos/metodologiaaccesibilidadespaciospublicos.pdf -- persisted retrieval-log/session_2026-09-28-research-batch-21-selection/76d6a5953998c402.pdf (page 24 of 69; footer ''-CERMI Comunidad de Madrid-''), text-extract derived artefact retrieval-log/session_2026-09-28-research-batch-21-selection/d1c5d900e01f9f10.json. R9 PRE-CHECKED: no DOI, municipal/DPO grey literature; not held by any evidence_sources row or staged candidate.', 'RESOLVED', 2, 0, 'NOT ADMITTED THIS BATCH -- an independent adversarial pass caught that this candidate was never actually staged in an earlier pass of this same batch, though its content was retrieved, read and quoted in exec_id=105''s findings_note; staging corrected here. tier_guess 2 is a HYPOTHESIS for a Co-2/DPO-endorsed reading, not a claim: the document''s title page and every page footer carry ''CERMI Comunidad de Madrid'' alongside the city council, but no methodology/acknowledgments statement of CERMI''s actual authorial role (a D-0178-style question) has been read. Whether this is genuine DPO co-production or a municipal document merely endorsed/co-branded by a DPO is the judgement the next reader must make from the full text.', 'GAP-049 lead (Co-1/DPO/multilingual pass, batch 21), corrected after an independent adversarial pass found it quoted-but-unstaged. Page 24 (''Pendientes longitudinales máximas'', within the ramp-specifications section) gives LONGITUDINAL slope maxima tiered by ramp length: ''Rampas de menos de 3 m. pendiente máxima 10%. Rampas de entre 3 y 10 m. pendiente máxima 8%.'' -- and separately, under ''Características generales'', ''La pendiente transversal máxima será del 2%'' (cross-slope, a DIFFERENT axis from parameter 3''s running-slope gradient -- cross-references REF-01011/extraction 72''s own ''(2%)'' ambiguity: 2% recurs here unambiguously as a CROSS-slope figure, evidence toward reading that ambiguity as cross-slope too). Page 10 (''Antecedentes'') separately states a more general, practical-use framing: ''pendientes superiores al 6% (limite que marca la ley) empiezan a tener problemas importantes para ser recorridas por muchas personas y a partir del 10% es impracticable'' -- also relevant to GAP-033 item 1 (ramp-vs-route scope): this passage discusses STREET/ROUTE slope as its own hazard category, distinct from the page-24 ramp specifications. NEXT: read the methodology/acknowledgments section for CERMI''s actual authorial role; if admitted, extraction(s) belong on parameter 3 x MOB for the page-24 longitudinal figures specifically (not the page-10 general/route framing, pending GAP-033''s resolution).', 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:34', NULL, 'retrieval-log/session_2026-09-28-research-batch-21-selection/d1c5d900e01f9f10.json', 'Rampas de menos de 3 m. pendiente máxima 10%.', '2026-09-28 07:34', 'session_2026-09-28-research-batch-21-selection');
