INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (70, 'REF-01010', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'UG', NULL, 'numerical', '1:12', 'rise:run ratio', 'A ramp provided under this Code shall— (a) have a gradient measured along the centre line, that is not steeper than 1:12 as prescribed in Figure 10 in the Schedule', 'Part II, section 12(3)(a)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '12', '3', NULL, 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Clause 12(1) frames the whole ramp requirement explicitly around wheelchair users: ''A ramp or series of ramps shall provide a safe, comfortable and convenient route for a wheelchair user.'' [VERBATIM-EXEMPT: Source is a binary PDF (persisted retrieval-log/session_2026-09-28-research-batch-21-selection/35c03adeb327d61c.pdf, sha256 35c03adeb327d61cd6c1943a09669626afe3624fd5ab1a19e4e5fed96ba41b8c, 2713066 bytes). quote_in_artefacts() decodes payloads as text (UTF-8/declared-charset); this PDF''s content streams are compressed (FlateDecode, the standard PDF text-stream compression), so the raw bytes do not decode to legible prose and no substring match is possible without format-specific extraction. The quote was independently verified twice: (1) read directly off this PDF''s extracted text via PyMuPDF in this session (page 15 of 42, section 12(3)); (2) cross-checked as a word-for-word match against the identical quotation reproduced in Mactaggart et al. 2024''s Supplementary Appendix 1 (REF-01009, persisted retrieval-log/session_2026-09-28-research-batch-21-selection/6ab420aabe807589.zip), which cites this Code as its own ramp-criterion source.]', '2026-09-28 06:46', 'session_2026-09-28-research-batch-21-selection', '2026-09-28 06:46', 'session_2026-09-28-research-batch-21-selection', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (71, 'REF-01009', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'UG', NULL, 'qualitative', 'all failed the overall accessibility criteria for a ramp: two were too steep and none had handrails', NULL, 'of three facilities with ramps, all reached the minimum required width and had textured, non-slip floors but two were too steep and none had handrails, meaning all failed the overall accessibility criteria for a ramp', 'Results', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Field measurement method (same article, Methods): ''For long ramps (over 2 m), 2-3 measurements were taken at various points along the length, and the steepest angle was recorded.'' No raw degree/ratio values per facility are given anywhere in the article or its supplementary appendices -- only the binary pass/fail against the composite standard (slope<=1:12 AND width>=1300mm AND handrails AND non-slip). This is corroborated at facility-aggregate level by Supplementary Table 2''s ''Ramp meets access standards'' row, which reads N=0, %=0 (of the 3 facilities with a ramp; 5 facilities audited in total) [supplementary docx persisted this session, retrieval-log/session_2026-09-28-research-batch-21-selection/6ab420aabe807589.zip -- the table''s own cells are bare digits, not independently quotable as a claim_text, so the corroborating figure is recorded here rather than as claimed_value]. D-0178/R13 POPULATION MATCH: this source''s Co-1 warrant (REF-01009.co1_provenance) is co-production by disabled youth researchers, none named as mobility-impaired (Deaf/albinism/visual-impairment are the three named) -- graded PROXY for MOB, following the REF-01003/extraction-49 precedent, not matched. || 2026-09-28 extraction_status CONFIRMED preliminary (Caught by an independent adversarial pass: this row''s notes name only the supplementary docx artefact (retrieval-log/.../6ab420aabe807589.zip) for the Table 2 corroboration; the row''s own claim_text (''of three facilities with ramps... all failed...'') is verbatim in the MAIN ARTICLE''s persisted JATS XML, retrieval-log/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/18ef7d575e63330c.xml (named on candidate 126''s locator, but not on this row). Named here for a reader who reaches this row without first reading the candidate.) || 2026-09-28 extraction_status CONFIRMED preliminary (CORRECTION, caught by an independent adversarial pass: this row''s notes said the R13 population match was ''graded PROXY for MOB, following the REF-01003/extraction-49 precedent''. That grade and that precedent are both wrong. Owner ruling 2026-09-25 (references/project-standards.md, ''A FACILITY AUDIT''S POPULATION GRADE DOES NOT TURN ON WHETHER ITS AUDITORS WERE DISABLED'') supersedes grading a facility audit''s population match on the auditors'' own disability; REF-01003 (a 23-participant walking study) is not the applicable precedent for a facility audit in any case -- REF-01006/REF-01007 are. The grade is now PARTIAL, corrected on the evidence_population_match row (match_id session_2026-09-28-resea-REF-01009-MOB).)', '2026-09-28 06:47', 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:40', 'session_2026-09-28-research-batch-21-selection', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (72, 'REF-01011', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'BR', NULL, 'numerical', '30,0', '% of all 90 audited buildings (NOT of the ~43 with a ramp -- see notes) meeting NBR 9050''s maximum-slope ramp requirement (Table 2, n=27/90)', 'Como resultado, dos 90 prédios avaliados, apenas 47,8% possuem rampa de acesso, destas 30,0% possuem inclinação máxima e 32,2% têm piso antiderrapante.', 'Resultados (Abstract/Resumo)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'R11: read from the PORTUGUESE ORIGINAL (this candidate''s own staging note flagged the English co-published PDF''s ''have maximum slope'' as ambiguous back-translation risk -- do not extract from it). The Portuguese resolves the ambiguity: ''possuem inclinação máxima'' is a checklist compliance item (Table 2 header: ''Inclinação máxima'', Sim/Não), i.e. ''meets the maximum-slope requirement'', not ''is at the limit''. SOURCE''S OWN DENOMINATOR IS AMBIGUOUS AND I DO NOT RESOLVE IT HERE: the abstract''s ''destas 30,0%'' (of these, 30.0%) reads as a fraction of the ~43 ramped buildings (47.8% of 90), but Table 2''s own numbers (n=27, categorias Sim/Não, Não n=63) give 27+63=90 -- i.e. 27/90=30.0% exactly, so the 30.0% is actually computed over the FULL 90-building sample (buildings with no ramp presumably scored ''Não'' on this item by default), not over the ramped subset the abstract''s prose implies. Both readings are recorded; the source''s own words are quoted as claim_text without resolving which the authors intended. Results section (Table 2) restates the same finding in stronger terms: ''[as rampas das USF], em sua maioria não obedece às normas preconizadas pela NBR 9050, porque apenas 30,0% foram construídas com inclinação máxima'' -- contrasted explicitly against a cited California primary-care study where 98,8% of ramps met slope requirements. NBR 9050''s own specific numeric threshold (ratio/%) is not quoted anywhere in this article; not filed as a research_code_lead since no clause value is in hand, only a citation to the standard''s name. Cross-slug note: this is the SECOND LMIC health-facility audit source in this cluster (with REF-01009/Mactaggart 2024) with a similar architecture (checklist-based ramp compliance audit, single-country, no control) and a similarly poor compliance rate for ramp slope. [VERBATIM-EXEMPT: Source is a binary PDF (persisted retrieval-log/session_2026-09-28-research-batch-21-selection/0894c27e153d9e7c.pdf, sha256 0894c27e153d9e7cb2de6e4ef57eade791cf39b95a105de16916b8cced03a151, 156406 bytes -- the Portuguese-original SciELO PDF, retrieved via an Internet Archive Wayback snapshot because live scielo.br/scielosp.org are blocked by a Bunny Shield WAF challenge). quote_in_artefacts() only decodes text payloads (UTF-8/declared-charset); this PDF''s content streams are FlateDecode-compressed so the raw bytes do not decode to legible prose. Text extracted via PyMuPDF in this session (page 1, Resumo/abstract, and corroborated verbatim in the Results section and Table 2 on a later page) -- both occurrences match this claim_text exactly.] || 2026-09-28 extraction_status CONFIRMED preliminary (THREE CORRECTIONS, caught by an independent adversarial pass, not self-caught. (1) THE TABLE 2 HEADER CARRIES A NUMBER THIS ROW''S NOTES OMITTED: word-level positional re-extraction of the persisted PDF (page 4) reads ''Item Inclinação máxima (2%) Piso antiderrapante Acabamento diferenciado...'' -- ''(2%)'' is genuinely attached to this item, not a column-bleed artefact as first assumed. 2% is NOT a plausible RUNNING-slope (longitudinal) maximum under NBR 9050 (whose longitudinal limits run roughly 5-8.33% depending on rise), but IS in the range NBR 9050 sets for a ramp''s CROSS-slope (inclinação transversal). Whether the authors mean cross-slope, or mistyped, cannot be settled from the bytes in hand -- but this row was filed on parameter 3 (TERM-001, ramp GRADIENT/running-slope) without surfacing that its own source may be measuring the other axis. Flagged as a material, unresolved ambiguity, not resolved either way. (2) SECTION MISATTRIBUTED: the ''não obedece às normas preconizadas pela NBR 9050... apenas 30,0%...'' sentence is in the DISCUSSÃO (Discussion), not ''(Abstract/Resumo)/Results'' as this row''s source_section says -- the 30,0% figure itself IS stated in the Resumo/abstract (unaffected), but the interpretive framing around it is discussion, not results. (3) THE CALIFORNIA COMPARISON IS ABOUT LENGTH/LANDING/WIDTH, NOT SLOPE: the sentence reads ''Tal achado é contrário a um estudo realizado na atenção primária da Califórnia, em que 98,8% das rampas presentes atendem ao padrão de comprimento, de desembarque e de largura'' -- length, landing and width standards. This row''s notes wrongly said ''contrasted... where 98.8% of ramps met slope requirements''. That characterization is withdrawn.) || 2026-09-28 extraction_status CONFIRMED preliminary (This row''s claimed_value ''30,0'' (comma-decimal) is not machine-parseable (see extraction_id=73, a dot-decimal restatement of the identical fact/quote, added after an independent adversarial pass caught the format issue). This row is NOT retracted -- read both together.)', '2026-09-28 06:55', 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:40', 'session_2026-09-28-research-batch-21-selection', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (73, 'REF-01011', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'BR', NULL, 'numerical', '30.0', '% of all 90 audited buildings (not the ~43 with a ramp -- see notes) that were graded as meeting the Table 2 ''Inclinação máxima'' checklist item (n=27/90)', 'Como resultado, dos 90 prédios avaliados, apenas 47,8% possuem rampa de acesso, destas 30,0% possuem inclinação máxima e 32,2% têm piso antiderrapante.', 'Resultados (Abstract/Resumo)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'FORMATTING CORRECTION OF extraction_id=72, caught by an independent adversarial pass: that row''s claimed_value ''30,0'' (Portuguese comma-decimal) is not parseable by this project''s own numeric readers (assess_cell.parse_bound / v_derived_figure_check), which expect dot-decimal or a:b ratio notation matching every other numerical row in the corpus. This row restates the identical fact and identical claim_text with claimed_value ''30.0'' (dot-decimal) so it is machine-readable; extraction_id=72 is NOT retracted (D-0168: a correction is a second row, not an overwrite) and carries the additional NBR-9050-(2%)/section/California-comparison corrections an adversarial pass also found -- read both rows together. comparator here is ''='' (a stated rate) rather than 72''s unset comparator, since ''='' more precisely describes what a rate figure asserts. [VERBATIM-EXEMPT: Same persisted PDF and passage as extraction_id=72 (retrieval-log/session_2026-09-28-research-batch-21-selection/0894c27e153d9e7c.pdf); see that row for the verbatim-exemption warrant.]', '2026-09-28 07:40', 'session_2026-09-28-research-batch-21-selection', '2026-09-28 07:40', 'session_2026-09-28-research-batch-21-selection', 'finding', '=');